import{_ as t,o as e,c as r,a2 as o}from"./chunks/framework.CAKCj7G0.js";const d=JSON.parse('{"title":"知识回顾-流程的切割","description":"","frontmatter":{},"headers":[],"relativePath":"DuOneClass/02.JavaScript/07. 知识回顾-流程的切割.md","filePath":"DuOneClass/02.JavaScript/07. 知识回顾-流程的切割.md"}'),n={name:"DuOneClass/02.JavaScript/07. 知识回顾-流程的切割.md"};function l(p,a,s,i,h,_){return e(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="知识回顾-流程的切割" tabindex="-1">知识回顾-流程的切割 <a class="header-anchor" href="#知识回顾-流程的切割" aria-label="Permalink to &quot;知识回顾-流程的切割&quot;">​</a></h1><h2 id="函数的作用" tabindex="-1">函数的作用 <a class="header-anchor" href="#函数的作用" aria-label="Permalink to &quot;函数的作用&quot;">​</a></h2><p>使用函数切割流程，不仅可以减少重复代码、还可以有效的降低整体复杂度</p><p><img src="https://s2.loli.net/2025/01/28/KHrGaJvPfdAlL9j.png" alt="20211209124426.png"></p><h2 id="函数的常见问题" tabindex="-1">函数的常见问题 <a class="header-anchor" href="#函数的常见问题" aria-label="Permalink to &quot;函数的常见问题&quot;">​</a></h2><h3 id="如何理解函数的参数、返回值、函数体" tabindex="-1"><strong>如何理解函数的参数、返回值、函数体？</strong> <a class="header-anchor" href="#如何理解函数的参数、返回值、函数体" aria-label="Permalink to &quot;**如何理解函数的参数、返回值、函数体？**&quot;">​</a></h3><p><img src="https://s2.loli.net/2025/01/28/neKmwXk1QqApIGY.png" alt="20211209125120.png"></p><p>参数：表示完成流程所需的<strong>必要信息</strong></p><p>返回值：表示完成流程后<strong>产生的结果</strong></p><p>函数体：表示具体的流程</p><p><strong>函数的参数、返回值只取决于函数的作用，与函数体无关</strong></p><h3 id="为什么我觉得有了函数之后-程序反而变得更复杂了" tabindex="-1">为什么我觉得有了函数之后，程序反而变得更复杂了？ <a class="header-anchor" href="#为什么我觉得有了函数之后-程序反而变得更复杂了" aria-label="Permalink to &quot;为什么我觉得有了函数之后，程序反而变得更复杂了？&quot;">​</a></h3><p>函数的核心作用，是为了让某一段复杂的流程变得简单。</p><p>如果在函数的帮助下，反而觉得流程变得复杂了，极有可能的原因是开发思想没有做相应的切割，导致思想负担过重。</p><p><strong>始终记住以下两点</strong>：</p><ol><li>定义函数时，只需要考虑这个函数如何实现即可，完全不需要考虑其他无关的东西。</li><li>调用函数时，只需要考虑向其传递什么参数，如何使用它的返回结果，完全无需考虑函数的具体实现。</li></ol><p>函数具有<strong>三要素</strong>：函数名、参数、返回值</p><p>只要具备三要素，就能书写函数体；只要具备三要素，就能完成函数调用。</p><h3 id="学习函数时不知道该如何切割流程怎么办" tabindex="-1">学习函数时不知道该如何切割流程怎么办？ <a class="header-anchor" href="#学习函数时不知道该如何切割流程怎么办" aria-label="Permalink to &quot;学习函数时不知道该如何切割流程怎么办？&quot;">​</a></h3><p>要完成一个函数声明，分为两步：</p><ol><li><p>设计函数</p><p>设计函数就是如何切割流程，具体来说就是设计出函数的三要素，这一步是最难的，目前无须同学们掌握，老师会帮你把函数设计好。</p></li><li><p>书写函数体</p><p>根据设计的三要素完成函数体，这一步就是现阶段练习的重点。</p></li></ol>',21)])])}const u=t(n,[["render",l]]);export{d as __pageData,u as default};
